mapper.select:
/* ChkLst01Mapper.selectChkptList */ SELECT '' AS chk , A.CMPNY_CD AS cmpnyCd , A.SITE_CD AS siteCd , B.SITE_NM AS siteNm , A.CHKLST_TYPE AS chkLstType , A.CHKPT_CD AS chkptCd , A.CHKPT_NM AS chkptNm , A.CHKPT_DESC AS chkptDesc , A.USE_YN AS useYn , A.MGMT_USER_CD AS mgmtUserCd , C.USER_NM AS mgmtUserNm
, A.LINK_SRC_CMPNY_CD AS linkSrcCmpnyCd FROM TB_CHKPT_TYPE_MGMT A INNER JOIN TB_SITE B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND B.USE_YN = 'Y' ) LEFT OUTER JOIN TB_USER C ON ( A.CMPNY_CD = C.CMPNY_CD AND A.MGMT_USER_CD = C.USER_CD AND C.USE_YN = 'Y' ) WHERE 1=1 AND A.CMPNY_CD = #{gvCmpnyCd}
AND A.SITE_CD = #{siteCd}
AND A.CHKPT_NM LIKE CONCAT('%', #{chkptNm}, '%')
AND A.CHKLST_TYPE = #{chkLstType}
AND A.USE_YN = #{useYn}

mapper.insert:
	/* ChkLst01Mapper.mergeChkptList */	
    INSERT INTO TB_CHKPT_TYPE_MGMT (
    	CMPNY_CD
    	, SITE_CD
    	, CHKLST_TYPE
    	, CHKPT_CD
    	, CHKPT_NM
    	, CHKPT_DESC
    	, MGMT_USER_CD
    	, USE_YN
    	, INSERT_NO
    	, INSERT_DATE
    	, UPDATE_NO
    	, UPDATE_DATE
   	)
   	VALUES(
   		#{gvCmpnyCd}
   		, #{siteCd}
   		, #{chkLstType}
   		, IFNULL(#{chkptCd}, prafta.FNC_CMM_SEQ_NEXTVAL(#{gvCmpnyCd}, 'CHKPT_CD'))
   		, #{chkptNm}
		, #{chkptDesc}
		, #{mgmtUserCd}
		, #{useYn}
		, #{gvUserCd}
		, now()
		, #{gvUserCd}
		, now() 
   	) AS NEW
   	ON DUPLICATE KEY UPDATE
	    CHKPT_NM    	= NEW.CHKPT_NM
	    , CHKPT_DESC 	= NEW.CHKPT_DESC
	    , MGMT_USER_CD	= NEW.MGMT_USER_CD
	    , USE_YN		= IFNULL(NEW.USE_YN, 'Y')
	    , UPDATE_NO   	= NEW.UPDATE_NO
	    , UPDATE_DATE 	= NOW()

/* ChkLst01Mapper.updateChkptList */
UPDATE TB_CHKPT_TYPE_MGMT
SET 
	USE_YN = 'N'
	, UPDATE_NO = #{gvUserCd}
	, UPDATE_DATE = now()
WHERE 1=1
  AND CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND CHKLST_TYPE = #{chkLstType}
  AND CHKPT_CD = #{chkptCd}

mapper.select:
/* ChkLst01Mapper.selectChkptRow */
SELECT
	A.CHKPT_NM				AS chkptNm
	, A.CHKPT_DESC			AS chkptDesc
	, A.USE_YN				AS useYn
	, A.MGMT_USER_CD		AS mgmtUserCd
	, A.LINK_SRC_CMPNY_CD	AS linkSrcCmpnyCd
FROM TB_CHKPT_TYPE_MGMT A
WHERE 1=1
  AND A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.CHKLST_TYPE = #{chkLstType}
  AND A.CHKPT_CD = #{chkptCd}

mapper.update:
/* ChkLst01Mapper.updateChkptMgmtUser */
UPDATE TB_CHKPT_TYPE_MGMT
SET
	MGMT_USER_CD = #{mgmtUserCd}
	, UPDATE_NO = #{gvUserCd}
	, UPDATE_DATE = NOW()
WHERE 1=1
  AND CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND CHKLST_TYPE = #{chkLstType}
  AND CHKPT_CD = #{chkptCd}

mapper.select:
/* ChkLst01Mapper.countUserSiteAuth */
SELECT COUNT(1)
FROM TB_USER_SITE_AUTH
WHERE 1=1
  AND CMPNY_CD = #{gvCmpnyCd}
  AND USER_CD = #{gvUserCd}
  AND SITE_CD = #{siteCd}
  AND USE_YN = 'Y'

/* ChkLst01Mapper.selectMenuButtonAuthCnt */
SELECT COUNT(*)
FROM (
	SELECT 1
	  FROM TB_SYST_AUTH_MENU
	 WHERE CMPNY_CD  = #{cmpnyCd}
	   AND AUTH_CD   = #{authCd}
	   AND MENU_D_ID = #{menuDId}
	   AND USE_YN    = 'Y'

	       AND BTN_SRCH = 'Y'
	       AND BTN_NEW = 'Y'
	       AND BTN_SAVE = 'Y'
	       AND BTN_DELT = 'Y'
	       AND 1 = 0

	 LIMIT 1
) T
